:root { --bg: #f4f2ee; --surface: #ffffff; --border: #d9d4cc; --text: #1f2429; --muted: #5b6470; --accent: #1d5c4b; --accent-strong: #154536; --accent-soft: #e4efe9; --danger: #a3271d; --danger-soft: #fbe9e7; --ring: 0 0 0 3px rgba(29, 92, 75, 0.35); --radius: 8px; }* { box-sizing: border-box; }html { background: var(--bg); color: var(--text); }body { margin: 0px; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif; font-size: 16px; line-height: 1.5; -webkit-font-smoothing: antialiased; }a { color: var(--accent); }a:focus-visible, button:focus-visible, input:focus-visible, select:focus-visible { outline: none; box-shadow: var(--ring); border-color: var(--accent); }.topbar { background: var(--surface); border-bottom: 1px solid var(--border); }.topbar-inner { max-width: 640px; margin: 0px auto; padding: 14px 20px; display: flex; align-items: center; justify-content: space-between; }.brand { display: flex; align-items: center; gap: 10px; font-weight: 700; letter-spacing: 0.01em; color: var(--text); text-decoration: none; }.brand-mark { width: 28px; height: 28px; border-radius: 7px; background: var(--accent); color: rgb(255, 255, 255); display: inline-flex; align-items: center; justify-content: center; font-size: 14px; font-weight: 800; }.topbar nav { font-size: 14px; color: var(--muted); }.topbar nav a { margin-left: 16px; color: var(--muted); text-decoration: none; }.topbar nav a:hover { color: var(--text); text-decoration: underline; }main { max-width: 640px; margin: 32px auto; padding: 0px 20px; }.card { background: var(--surface); border: 1px solid var(--border); border-radius: 12px; padding: 28px; box-shadow: rgba(20, 24, 30, 0.04) 0px 1px 2px, rgba(20, 24, 30, 0.05) 0px 8px 24px; }h1 { font-size: 26px; margin: 0px 0px 4px; letter-spacing: -0.01em; }h2 { font-size: 17px; margin: 0px 0px 12px; }.lede { margin: 0px 0px 24px; color: var(--muted); }fieldset { border: 0px; padding: 0px; margin: 0px 0px 20px; }legend { font-size: 13px; font-weight: 600; color: var(--muted); text-transform: uppercase; letter-spacing: 0.06em; padding: 0px; margin-bottom: 12px; }.field { display: flex; flex-direction: column; margin-bottom: 14px; }.field label { font-size: 14px; font-weight: 600; margin-bottom: 6px; }.field .hint { font-size: 13px; color: var(--muted); margin-top: 4px; }.row { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }.row-3 { display: grid; grid-template-columns: 2fr 1fr 1fr; gap: 14px; }@media (max-width: 480px) {
  .row, .row-3 { grid-template-columns: 1fr; }
}input[type="text"], input[type="email"], input[type="password"], input[type="tel"], select { font: inherit; padding: 10px 12px; border: 1px solid var(--border); border-radius: var(--radius); background: rgb(255, 255, 255); color: var(--text); width: 100%; }select { appearance: auto; }.check { display: flex; align-items: center; gap: 10px; font-size: 14px; }.check input { width: 18px; height: 18px; accent-color: var(--accent); }.btn { font-style: inherit; font-variant: inherit; font-stretch: inherit; font-size: inherit; line-height: inherit; font-family: inherit; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; font-language-override: inherit; font-weight: 600; padding: 12px 18px; border-radius: var(--radius); border: 1px solid var(--accent-strong); background: var(--accent); color: rgb(255, 255, 255); cursor: pointer; width: 100%; }.btn:hover { background: var(--accent-strong); }.btn[disabled] { opacity: 0.65; cursor: progress; }.alert { display: none; margin: 0px 0px 16px; padding: 10px 12px; border-radius: var(--radius); background: var(--danger-soft); color: var(--danger); font-size: 14px; }.alert[data-visible="true"] { display: block; }.summary { border: 1px solid var(--border); border-radius: 10px; padding: 16px 18px; margin: 0px 0px 24px; background: rgb(251, 250, 248); }.summary-head { display: flex; justify-content: space-between; align-items: baseline; margin-bottom: 10px; }.summary-head h2 { margin: 0px; }.account { font-size: 13px; color: var(--muted); }.summary ul { list-style: none; margin: 0px; padding: 0px; }.summary li { display: flex; justify-content: space-between; padding: 6px 0px; font-size: 15px; }.summary li .qty { color: var(--muted); margin-left: 6px; }.summary .totals { border-top: 1px solid var(--border); margin-top: 8px; padding-top: 8px; }.summary .totals li.total { font-weight: 700; font-size: 16px; }.skeleton { color: var(--muted); font-size: 14px; }.confirmation { border: 1px solid rgb(185, 217, 201); background: var(--accent-soft); border-radius: 10px; padding: 20px; margin-bottom: 16px; }.confirmation h2 { margin: 0px 0px 6px; color: var(--accent-strong); }.confirmation p { margin: 0px 0px 6px; }.support { position: fixed; right: 20px; bottom: 20px; width: 260px; background: var(--surface); border: 1px solid var(--border); border-radius: 12px; box-shadow: rgba(20, 24, 30, 0.12) 0px 10px 30px; font-size: 13px; overflow: hidden; }.support-head { background: var(--accent); color: rgb(255, 255, 255); padding: 8px 12px; font-weight: 600; }.support-body { padding: 10px 12px; color: var(--muted); }.support-body .bubble { background: var(--bg); border-radius: 8px; padding: 8px 10px; margin-top: 6px; color: var(--text); }@media (max-width: 720px) {
  .support { display: none; }
}footer { max-width: 640px; margin: 0px auto 40px; padding: 0px 20px; font-size: 13px; color: var(--muted); }footer code { background: rgb(235, 232, 226); padding: 1px 6px; border-radius: 4px; }.visually-hidden { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0px, 0px, 0px, 0px); }

